args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?director ?directorLabel ?b WHERE {
  VALUES ?film { dbr:The_Enchanted_Desna dbr:Neal_of_the_Navy }
  ?film dbo:director ?director .
  OPTIONAL {
    { ?director dbo:birthDate ?b } UNION { ?director dbp:birthDate ?b } UNION { ?director dbp:birth_date ?b } UNION { ?director dbp:born ?b }
  }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = 'en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?olderFilm ?olderFilmLabel WHERE {
  BIND(dbr:The_Enchanted_Desna AS ?f1)
  BIND(dbr:Neal_of_the_Navy AS ?f2)
  ?f1 dbo:director ?d1 .
  ?f2 dbo:director ?d2 .

  OPTIONAL { { ?d1 dbo:birthDate ?b1 } UNION { ?d1 dbp:birthDate ?b1 } UNION { ?d1 dbp:birth_date ?b1 } UNION { ?d1 dbp:born ?b1 } }
  OPTIONAL { { ?d2 dbo:birthDate ?b2 } UNION { ?d2 dbp:birthDate ?b2 } UNION { ?d2 dbp:birth_date ?b2 } UNION { ?d2 dbp:born ?b2 } }

  {
    FILTER(bound(?b1) && bound(?b2) && (?b1 < ?b2))
    BIND(?f1 AS ?olderFilm)
  }
  UNION
  {
    FILTER(bound(?b1) && bound(?b2) && (?b2 < ?b1))
    BIND(?f2 AS ?olderFilm)
  }

  OPTIONAL { ?olderFilm rdfs:label ?olderFilmLabel FILTER(lang(?olderFilmLabel) = 'en') }
}

